async def wait_for_started(task: asyncio.Task[Any], started: asyncio.Event) -> None:
    """Surface an unfinished seam immediately instead of waiting for a gate timeout."""
    await asyncio.sleep(0)
    if task.done():
        await task
    await asyncio.wait_for(started.wait(), timeout=1)


@pytest.mark.sources
async def test_source_adapters_translate_valid_responses() -> None:
    def handler(request: httpx.Request) -> httpx.Response:
        if request.url.path == "/pypi/demo/json":
            return httpx.Response(
                200, json={"info": {"version": "2.0", "requires_python": ">=3.10"}}
            )
        if request.url.path == "/v1/query":
            return httpx.Response(
                200,
                json={
                    "vulns": [
                        {"id": "GHSA-1", "aliases": ["CVE-1"], "summary": "fixture"},
                        {"id": "PYSEC-1", "aliases": ["CVE-1", "CVE-2"]},
                        {"id": "PYSEC-2", "aliases": ["CVE-2"]},
                    ]
                },
            )
        if request.url.path.endswith(":dependencies"):
            return httpx.Response(
                200,
                json={
                    "nodes": [
                        {
                            "versionKey": {"system": "PYPI", "name": "demo", "version": "1.0"},
                            "relation": "SELF",
                        },
                        {
                            "versionKey": {"system": "PYPI", "name": "direct", "version": "1.0"},
                            "relation": "DIRECT",
                        },
                    ]
                },
            )
        if request.url.path.startswith("/v3/systems/"):
            return httpx.Response(
                200,
                json={
                    "versionKey": {"system": "PYPI", "name": "demo", "version": "1.0"},
                    "licenses": ["MIT"],
                    "publishedAt": "2024-01-01T00:00:00Z",
                },
            )
        raise AssertionError(f"unexpected request {request.method} {request.url}")

    coordinate = DependencyCoordinate("demo", "1.0")
    async with httpx.AsyncClient(transport=httpx.MockTransport(handler)) as client:
        http = JsonHttpClient(client)
        metadata = await PyPIClient(http, base_url="https://fixture").fetch_metadata(coordinate)
        advisories = await OSVClient(http, base_url="https://fixture").fetch_vulnerabilities(
            coordinate
        )
        supply_chain = await DepsDevClient(http, base_url="https://fixture").fetch_supply_chain(
            coordinate
        )

    assert metadata.latest_version == "2.0"
    assert len(advisories) == 1
    assert advisories[0].identifier == "GHSA-1"
    assert set(advisories[0].aliases) == {"CVE-1", "CVE-2", "PYSEC-1", "PYSEC-2"}
    assert supply_chain.licenses == ("MIT",)
    assert supply_chain.direct_dependency_count == 1


class GateHttp:
    def __init__(self) -> None:
        self.gate = StartGate(2)

    async def request_json(
        self,
        service: ServiceName,
        method: str,
        url: str,
        *,
        json: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        await self.gate.wait()
        if url.endswith(":dependencies"):
            return {
                "nodes": [
                    {
                        "versionKey": {"system": "PYPI", "name": "demo", "version": "1.0"},
                        "relation": "SELF",
                    }
                ]
            }
        return {
            "versionKey": {"system": "PYPI", "name": "demo", "version": "1.0"},
            "licenses": [],
        }


@pytest.mark.sources
async def test_deps_dev_requests_start_concurrently() -> None:
    fake = GateHttp()
    client = DepsDevClient(cast(JsonHttpClient, fake), base_url="https://fixture")
    task = asyncio.create_task(client.fetch_supply_chain(DependencyCoordinate("demo", "1.0")))

    await wait_for_started(task, fake.gate.all_started)
    assert fake.gate.starts == 2
    fake.gate.release.set()

    result = await task
    assert result.direct_dependency_count == 0


@pytest.mark.cache
async def test_cache_expires_and_evicts_lru() -> None:
    clock = FakeClock()
    cache = AsyncTTLCache[str, str](ttl_seconds=10, max_entries=2, clock=clock)
    await cache.put("a", "A")
    await cache.put("b", "B")
    assert await cache.get("a") == "A"
    await cache.put("c", "C")
    assert await cache.get("b") is None
    clock.advance(10)
    assert await cache.get("a") is None
    assert await cache.get("c") is None
    assert await cache.size() == 0


def scanner_with(
    metadata: FakeMetadataSource | None = None,
    vulnerabilities: FakeVulnerabilitySource | None = None,
    supply_chain: FakeSupplyChainSource | None = None,
    *,
    cache: MemoryCache | AsyncTTLCache[str, PackageAssessment] | None = None,
    max_concurrent_packages: int = 8,
) -> DependencyScanner:
    return DependencyScanner(
        metadata_source=metadata or FakeMetadataSource(),
        vulnerability_source=vulnerabilities or FakeVulnerabilitySource(),
        supply_chain_source=supply_chain or FakeSupplyChainSource(),
        cache=cache or MemoryCache(),
        max_concurrent_packages=max_concurrent_packages,
    )


@pytest.mark.orchestration
async def test_three_sources_start_concurrently() -> None:
    gate = StartGate(3)
    scanner = scanner_with(
        FakeMetadataSource(gate=gate),
        FakeVulnerabilitySource(gate=gate),
        FakeSupplyChainSource(gate=gate),
    )
    task = asyncio.create_task(scanner.assess(DependencyCoordinate("demo", "1.0")))
    await wait_for_started(task, gate.all_started)
    assert gate.starts == 3
    gate.release.set()
    assert (await task).complete


@pytest.mark.orchestration
async def test_package_limit_and_order_are_preserved() -> None:
    gate = StartGate(2)
    metadata = FakeMetadataSource(gate=gate)
    scanner = scanner_with(metadata=metadata, max_concurrent_packages=2)
    coordinates = [
        DependencyCoordinate("first", "1.0"),
        DependencyCoordinate("second", "1.0"),
        DependencyCoordinate("third", "1.0"),
    ]
    task = asyncio.create_task(scanner.scan(coordinates))
    await wait_for_started(task, gate.all_started)
    await asyncio.sleep(0)
    assert metadata.calls == 2
    gate.release.set()
    report = await task
    assert [item.coordinate.name for item in report.results] == ["first", "second", "third"]


@pytest.mark.orchestration
async def test_partial_result_is_attributed_and_not_cached() -> None:
    metadata = FakeMetadataSource()
    vulnerabilities = FakeVulnerabilitySource(
        failure=source_failure(ServiceName.OSV, FailureKind.UNAVAILABLE)
    )
    supply_chain = FakeSupplyChainSource()
    scanner = scanner_with(metadata, vulnerabilities, supply_chain)
    coordinate = DependencyCoordinate("demo", "1.0")

    first = await scanner.assess(coordinate)
    second = await scanner.assess(coordinate)

    assert not first.complete
    assert first.assessment is not None
    assert first.assessment.vulnerabilities is None
    assert first.failures[0].service is ServiceName.OSV
    assert second.cache_status is CacheStatus.MISS
    assert (metadata.calls, vulnerabilities.calls, supply_chain.calls) == (2, 2, 2)


@pytest.mark.orchestration
async def test_complete_result_is_cached_and_identical_misses_coalesce() -> None:
    gate = StartGate(3)
    metadata = FakeMetadataSource(gate=gate)
    vulnerabilities = FakeVulnerabilitySource(gate=gate)
    supply_chain = FakeSupplyChainSource(gate=gate)
    cache = AsyncTTLCache[str, PackageAssessment](ttl_seconds=60, max_entries=20)
    scanner = scanner_with(metadata, vulnerabilities, supply_chain, cache=cache)
    coordinate = DependencyCoordinate("demo", "1.0")

    callers = [asyncio.create_task(scanner.assess(coordinate)) for _ in range(5)]
    await asyncio.sleep(0)
    if all(task.done() for task in callers):
        await asyncio.gather(*callers)
    await asyncio.wait_for(gate.all_started.wait(), timeout=1)
    gate.release.set()
    results = await asyncio.gather(*callers)
    cached = await scanner.assess(coordinate)

    assert (metadata.calls, vulnerabilities.calls, supply_chain.calls) == (1, 1, 1)
    assert sum(result.cache_status is CacheStatus.MISS for result in results) == 1
    assert sum(result.cache_status is CacheStatus.COALESCED for result in results) == 4
    assert cached.cache_status is CacheStatus.HIT


@pytest.mark.orchestration
async def test_cancelling_final_waiter_cancels_sources() -> None:
    gate = StartGate(3)
    scanner = scanner_with(
        FakeMetadataSource(gate=gate),
        FakeVulnerabilitySource(gate=gate),
        FakeSupplyChainSource(gate=gate),
    )
    task = asyncio.create_task(scanner.assess(DependencyCoordinate("demo", "1.0")))
    await wait_for_started(task, gate.all_started)
    task.cancel()
    with pytest.raises(asyncio.CancelledError):
        await task
    for _ in range(5):
        if gate.cancelled == 3:
            break
        await asyncio.sleep(0)
    assert gate.cancelled == 3


@pytest.mark.transport
async def test_api_maps_complete_and_failed_reports() -> None:
    complete_scanner = scanner_with()
    failed_scanner = scanner_with(
        FakeMetadataSource(failure=source_failure(ServiceName.PYPI)),
        FakeVulnerabilitySource(failure=source_failure(ServiceName.OSV)),
        FakeSupplyChainSource(failure=source_failure(ServiceName.DEPS_DEV)),
    )
    request = {"dependencies": [{"name": "demo", "version": "1.0"}]}

    async with httpx.AsyncClient(
        transport=httpx.ASGITransport(app=create_app(scanner=complete_scanner)),
        base_url="http://test",
    ) as client:
        complete = await client.post("/v1/scans", json=request)
    async with httpx.AsyncClient(
        transport=httpx.ASGITransport(app=create_app(scanner=failed_scanner)),
        base_url="http://test",
    ) as client:
        failed = await client.post("/v1/scans", json=request)

    assert complete.status_code == 200
    assert complete.json()["status"] == "complete"
    assert failed.status_code == 503
    assert failed.json()["status"] == "failed"


class NeverCalledScanner:
    async def scan(self, dependencies: object) -> ProjectScanReport:
        raise AssertionError("path rejection must happen before scanning")


@pytest.mark.transport
async def test_agent_tool_rejects_parent_escape(tmp_path: Path) -> None:
    workspace = tmp_path / "workspace"
    workspace.mkdir()
    (tmp_path / "requirements.lock").write_text("secret==1.0\n", encoding="utf-8")
    tool = DependencyScanTool(
        workspace_root=workspace,
        scanner=cast(DependencyScanner, NeverCalledScanner()),
    )

    result = await tool.execute("../requirements.lock")

    assert result["status"] == "invalid_manifest_path"


@pytest.mark.transport
async def test_project_report_status_semantics() -> None:
    scanner = scanner_with(
        vulnerabilities=FakeVulnerabilitySource(
            failure=source_failure(ServiceName.OSV, FailureKind.TIMEOUT)
        )
    )
    partial = await scanner.scan([DependencyCoordinate("demo", "1.0")])
    assert partial.status is ScanStatus.PARTIAL
